INSERT INTO public.scraper_sources (id, source_name, society, base_url, default_event_type, pagination_type, pagination_template, max_pages_hint, detail_is_multipage, active, extraction_instructions) VALUES
  (134, 'EULAR Events', 'EULAR', 'https://www.eular.org/event?search=&date=upcoming&tags=&type=all&country=all', 'mixed', 'page_query', 'https://www.eular.org/event/page/{page}?search=&date=upcoming&tags=&type=all&country=all', 2, FALSE, TRUE, 'Odoo events site. Listing walked by the extractor (page 1 /event?date=upcoming, then the /event/page/N link): one article per event with title, UTC start datetime (converted to Europe/Zurich), ''City, Country'' or TBC/TBD, optional tag. Event page sidebar gives local start/end dates (a 00:00 end is exclusive) and a ''Go to website'' organiser link; the page itself has no prose. edu.eular.org organiser links print ''Cost: EUR n''. Other organiser landing pages get ONE validated hop (check_url_safe + fetch_validated) for a description (meta/og or first real paragraph; text naming another year than the event is dropped) and fees (JSON-LD offers or fee table); if no fees there, ONE more hop to a registration/fees link on the same host. Cap 20 extra requests per run; otherwise a one-line template description from page fields.'),
  (135, 'PCR Courses', 'PCR', 'https://www.pcronline.com/Courses', 'mixed', 'single_page', NULL, 1, TRUE, TRUE, 'eZ Publish, server-rendered. /Courses has one a.single-content-item per course with ''Title - dates'' in p.navigation-link and a one-line blurb; undated and past cards are skipped, PCR Gulf Valves (302 to GulfPCR-GIM) is dropped as a duplicate. Course page: Event JSON-LD (regex-read, sometimes invalid JSON) gives venue/city/country, dates come from the card. Fees on the course''s own /Register page: .pricing-item packages (category, current price for the pricing-active timeframe, other timeframes as price-text/price-small), Innovators Day uses its STAND ALONE matrix. Exhibitor/industry/emerging-company categories are skipped.'),
  (136, 'SIU Events and Congress', 'SIU', 'https://www.siu-urology.org/events', 'mixed', 'single_page', NULL, 1, TRUE, TRUE, 'Custom PHP page: /events is one page of blocks opened by <a name=eventNN>, each with h3 title, free-text date line (year sometimes missing: taken from the footer copyright year), location line and free HTML. Past, undated and in-progress programmes are dropped. The annual Congress is not on that page: the newest /congress-YYYY/highlights page gives dates, city and edition, /general-information the venue and /registration the euro fee tables (IN PERSON / VIRTUAL ONLY x EARLY / REGULAR, member / non-member / Bench-to-Bedside).'),
  (137, 'ESHRE Campus and Annual Meeting', 'ESHRE', 'https://www.eshre.eu/en/Education/Calendar-Campus-events', 'mixed', 'single_page', NULL, 1, TRUE, TRUE, 'Sitecore, server-rendered. The Campus calendar is one page of a>div.grid-item cards (p.w-title, blurb, fa-map-marker ''City, Country'', fa-calendar ''dd-dd Month yyyy'', class places-available/fully-booked). The Annual Meeting (not in that calendar) comes from /Annual-Meeting: ''<year> Annual Meeting ... will be held from D to D Month YYYY in City, Country'' with a link to /en/Annual-Meeting/ESHRE-<year> (venue). Workshop pages give venue widget, EACCME credits and a <event>/Registration page with a Member / Allied-student / Non-member x Early / Standard table in EUR.'),
  (139, 'ASH Meetings', 'American Society of Hematology (ASH)', 'https://www.hematology.org/meetings', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'Single /meetings page with five sections: ASH Annual Meeting and four Highlights of ASH programmes (North America in four cities, Asia-Pacific, MEMENA, Latin America). Each section states the NEXT edition in a ''taking place <dates>, in <City>, <Country>'' sentence; programme pages still carry last edition''s text (Kuala Lumpur, Istanbul), so dates/venue are anchored on the current edition''s date line. Fees are USD HTML grids on /registration (/registration-information for the Annual Meeting), used only when the page names the edition year. Annual Meeting late-breaking abstract deadline is read from /abstracts.'),
  (140, 'AAN Upcoming Conferences', 'American Academy of Neurology (AAN)', 'https://www.aan.com/events/upcoming-events', 'conference', 'single_page', NULL, 1, FALSE, FALSE, 'Server-rendered listing: per series an <h4> link, then <p> blocks ''City and online<br>date<br>date'' where a place line applies to the dates under it. Editions within 18 months only. Series pages show the next edition or a thank-you for the PAST edition, so page text is used only when its header date matches the shell. No fees are public yet (Annual Meeting registration opens November 2026). Nothing from this site is sent to llm_call (site forbids AI use); description and specialty are deterministic.'),
  (141, 'AAD Meetings', 'American Academy of Dermatology (AAD)', 'https://www.aad.org/member/meetings/events', 'mixed', 'single_page', NULL, 1, FALSE, FALSE, 'The recon URL (/member/meetings/events/locations) is only the dates page (Annual 2027/2028, summer meetings). The real listing is /member/meetings/events, a card deck: DermCatalyst (postponed, skipped), Hands-On: Cosmetics (own page with date line, venue and Rates), the 2027 Annual Meeting microsite (/member/meetings-education/am27, fees public at /registration/fees: Early bird / Standard grid). Editions without a page (Annual 2028, summer 2027) come from the dates page. Hands-On rates are shown publicly but only members can register. Nothing from this site is sent to llm_call (site forbids AI use); description and specialty are deterministic.'),
  (142, 'CNS Meetings', 'Congress of Neurological Surgeons (CNS)', 'https://www.cns.org/meetings/calendar', 'mixed', 'single_page', NULL, 1, FALSE, FALSE, 'The calendar is a JS month grid mixing events with on-demand series and award windows. The three category listings (/meetings/courses, /meetings/joint-section-meetings, /meetings/other-neurosurgical-meetings) render div.list-item cards (title link /meetings-detail/<slug>, EventStartDate_s, EventEndDate_s, Teaser_s) and are loaded with the browser; spans over 14 days and past events are dropped. The Annual Meeting comes from the static /meetings/past-and-future-annual-meetings; its microsite /annualmeeting/overview holds the Member and Non-member fee grids (Early Bird/Advanced/Regular) and is attached only to the edition whose year the headers carry. Detail pages: ''<format>/<title>/<venue | city, ST>/<dates>'', Pricing table, Hotel, ACCME credit text. Third-party symposia link to the organiser page, read for public fees via fetch_validated. Nothing from this site is sent to llm_call (site forbids AI use); description and specialty are deterministic.'),
  (143, 'AUGIS Events', 'Association of Upper Gastrointestinal Surgeons of GB&I (AUGIS)', 'https://www.augis.org/Events', 'conference', 'single_page', NULL, 1, FALSE, TRUE, '/Events ''View as List'' is a plain table (<time datetime>, link to /Events/Event-Booking/EventId/<n>, venue); no load-more exists, the list is complete. Booking pages only repeat title/date/venue and start a booking flow that asks members to log in, so no fee is public. Events with an /Our-Events/<slug> info page (left navigation) get a description; its Programme link is a Cvent summary read once via fetch_validated for start time, full venue name and city. The next Annual Scientific Meeting (2027, ICC Wales) is announced only as a home-page banner sentence and is added from it.')
